     * echo server returning the nested body and assert the leaf types. */
    test(
      'bhv operations 101 getGroupedCategories decodes nested container leaves into Category',
      () async {
        final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
        server.listen((request) {
          request.response
            ..statusCode = 200
            ..headers.contentType = ContentType.json
            ..write(
              '[{"a":{"id":1,"name":"Dogs"}},{"b":{"id":2,"name":"Cats"}}]',
            )
            ..close();
        });

        try {
          final config = ConfigurationBuilder()
              .baseUrl('http://localhost:${server.port}')
              .build();
          final api = StoreApi(apiClient: DefaultApiClient(), config: config);

          final result = await api.getGroupedCategories(null);
          expect(result, hasLength(2));

          final first = result[0]['a'];
          expect(first, isA<Category>());
          expect(first!.id, equals(1));
          expect(first.name, equals('Dogs'));

          final second = result[1]['b'];
          expect(second, isA<Category>());
          expect(second!.id, equals(2));
          expect(second.name, equals('Cats'));
        } finally {
          await server.close();
        }
      },
    );

